#endif


extension ScoreResult: Equatable, Hashable {
    public static func ==(lhs: ScoreResult, rhs: ScoreResult) -> Bool {
        if lhs.correct != rhs.correct {
            return false
        }
        if lhs.matchedAnswer != rhs.matchedAnswer {
            return false
        }
        if lhs.expected != rhs.expected {
            return false
        }
        if lhs.feedback != rhs.feedback {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(correct)
        hasher.combine(matchedAnswer)
        hasher.combine(expected)
        hasher.combine(feedback)
    }
}



