 * A removed item's forwarding record.
 */
public struct TombstoneRecord {
    public var itemId: String
    public var removedIn: String
    public var reason: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(itemId: String, removedIn: String, reason: String?) {
        self.itemId = itemId
        self.removedIn = removedIn
        self.reason = reason
    }
}

#if compiler(>=6)
extension TombstoneRecord: Sendable {}
#endif


extension TombstoneRecord: Equatable, Hashable {
    public static func ==(lhs: TombstoneRecord, rhs: TombstoneRecord) -> Bool {
        if lhs.itemId != rhs.itemId {
            return false
        }
        if lhs.removedIn != rhs.removedIn {
            return false
        }
        if lhs.reason != rhs.reason {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(itemId)
        hasher.combine(removedIn)
        hasher.combine(reason)
    }
}



