// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum WordStatus {
    
    /**
     * Exact match after normalization.
     */
    case matched
    /**
     * Close enough (small edit distance) — counts toward the score.
     */
    case near
    /**
     * Something else was said in its place.
     */
    case substituted
    /**
     * Target word not found in the transcript.
     */
    case missed
}


#if compiler(>=6)
extension WordStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWordStatus: FfiConverterRustBuffer {
    typealias SwiftType = WordStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WordStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .matched
        
        case 2: return .near
        
        case 3: return .substituted
        
        case 4: return .missed
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WordStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .matched:
            writeInt(&buf, Int32(1))
        
        
        case .near:
            writeInt(&buf, Int32(2))
        
        
        case .substituted:
            writeInt(&buf, Int32(3))
        
        
        case .missed:
            writeInt(&buf, Int32(4))
        
        }
    }
}


